dashboard.definition:
{
  "title": "PulseForge · Non-profit: staff identity attack and cloud-mail exfiltration of donor data",
  "description": "Show credential stuffing against staff identities and a cloud-mail exfiltration of donor records.",
  "inputs": {
    "input_global_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    },
    "input_run": {
      "type": "input.dropdown",
      "title": "Scenario run (replay session)",
      "options": {
        "token": "run_tok",
        "defaultValue": "*",
        "items": [
          {
            "label": "All runs",
            "value": "*"
          }
        ],
        "createSearchJobOnChange": false,
        "clearDefaultOnSelection": false
      },
      "dataSources": {
        "primary": "ds_runs"
      },
      "context": {}
    },
    "input_phase": {
      "type": "input.dropdown",
      "title": "Incident phase",
      "options": {
        "token": "phase_tok",
        "defaultValue": "*",
        "items": [
          {
            "label": "All phases",
            "value": "*"
          }
        ],
        "createSearchJobOnChange": false,
        "clearDefaultOnSelection": false
      },
      "dataSources": {
        "primary": "ds_phase_list"
      },
      "context": {}
    },
    "input_index": {
      "type": "input.text",
      "title": "Index",
      "options": {
        "token": "index_tok",
        "defaultValue": "dev_test_replay"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_1": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### **PulseForge** · Security investigation\n**Nonprofit Ngo Global Aid · Humanitarian and donor platforms**  ·  `ind_nonprofit_donor_platform_attack`\n\nShow credential stuffing against staff identities and a cloud-mail exfiltration of donor records.\n\n_Live searches over the run; authentic recorded/native telemetry; industry framing is editorial._",
        "fontColor": "#ececea",
        "backgroundColor": "#17191b",
        "fontSize": "default"
      }
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#d4764f",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Events in run",
      "dataSources": {
        "primary": "ds_1"
      },
      "showProgressBar": true
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#6f9db5",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Telemetry sources (sourcetypes)",
      "dataSources": {
        "primary": "ds_2"
      },
      "showProgressBar": true
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#a79fc4",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Hosts observed",
      "dataSources": {
        "primary": "ds_3"
      },
      "showProgressBar": true
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#c9a24a",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Attack progression span",
      "dataSources": {
        "primary": "ds_4"
      },
      "showProgressBar": true
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#6fa387",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Progression phases observed",
      "dataSources": {
        "primary": "ds_5"
      },
      "showProgressBar": true
    },
    "viz_7": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#c9786f",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Contributing packs",
      "dataSources": {
        "primary": "ds_6"
      },
      "showProgressBar": true
    },
    "viz_8": {
      "type": "splunk.column",
      "options": {
        "stackMode": "stacked",
        "seriesColors": [
          "#d4764f",
          "#6f9db5",
          "#c9a24a",
          "#6fa387",
          "#a79fc4",
          "#c9786f",
          "#8fb0a8",
          "#b8b09a"
        ],
        "legendDisplay": "bottom",
        "yAxisTitleText": "Events",
        "xAxisTitleText": "Seconds since the first event of the run",
        "backgroundColor": "#22262a"
      },
      "title": "Incident timeline · events by phase",
      "description": "Event volume over the run's own clock, split by incident phase.",
      "dataSources": {
        "primary": "ds_7"
      },
      "showProgressBar": true
    },
    "viz_9": {
      "type": "splunk.bar",
      "options": {
        "seriesColors": [
          "#d4764f"
        ],
        "backgroundColor": "#22262a",
        "xAxisTitleText": "Events",
        "legendDisplay": "off"
      },
      "title": "Events by phase (click to filter the page)",
      "description": "Click a bar to set the Incident phase filter; choose All phases to reset.",
      "dataSources": {
        "primary": "ds_8"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "phase_tok",
                "key": "name"
              }
            ]
          }
        }
      ]
    },
    "viz_10": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Detection status: **NOT VERIFIED**\nNo vendor add-on, CIM or Enterprise Security content is installed in any lab, so no detection is claimed. Detection work needs the add-ons for the constituent sourcetypes plus reviewed SPL; the constituent native packs' contracts list their own expectations.\n\n**Severity:** not asserted. PulseForge does not assign a severity to replayed telemetry; no detection has fired in this lab.",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a"
      }
    },
    "viz_11": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Original analytics (Splunk Security Content)\nDetections whose published test data is a dataset replayed by this scenario:\n\n- [ASL AWS Create Access Key](https://research.splunk.com/cloud/81a9f2fe-1697-473c-af1d-086b0d8b63c8/) · Hunting · upstream validation: NOT_TESTED\n- [ASL AWS Create Policy Version to allow all resources](https://research.splunk.com/cloud/22cc7a62-3884-48c4-82da-592b8199b72f/) · TTP · upstream validation: NOT_TESTED\n- [Azure Automation Runbook Created](https://research.splunk.com/cloud/178d696d-6dc6-4ee8-9d25-93fee34eaf5b/) · TTP · upstream validation: NOT_TESTED\n- [Cisco Duo Bulk Policy Deletion](https://research.splunk.com/application/983be012-e408-4cb0-b87f-6756bb5f7047/) · TTP · upstream validation: NOT_TESTED\n- [Cisco Duo Set User Status to Bypass 2FA](https://research.splunk.com/application/8728d224-9cd5-4aa7-b75f-f8520a569979/) · TTP · upstream validation: NOT_TESTED\n- [Detect Web Access to Decommissioned S3 Bucket](https://research.splunk.com/web/3a1d8f62-5b9c-4e7d-b8f3-9d6a8e2f5e1f/) · Anomaly · upstream validation: NOT_TESTED\n- [GCP Successful Single-Factor Authentication](https://research.splunk.com/cloud/40e17d88-87da-414e-b253-8dc1e4f9555b/) · TTP · upstream validation: NOT_TESTED\n- [GSuite Email Suspicious Attachment](https://research.splunk.com/cloud/6d663014-fe92-11eb-ab07-acde48001122/) · Anomaly · upstream validation: NOT_TESTED\n- [Gsuite Outbound Email With Attachment To External Domain](https://research.splunk.com/cloud/dc4dc3a8-ff54-11eb-8bf7-acde48001122/) · Hunting · upstream validation: NOT_TESTED\n- [O365 Email Password and Payroll Compromise Behavior](https://research.splunk.com/cloud/e36de71a-6bdc-4002-98ff-e3e51b0d8f96/) · TTP · upstream validation: NOT_TESTED\n- [O365 Email Receive and Hard Delete Takeover Behavior](https://research.splunk.com/cloud/b66aeaa4-586f-428b-8a2b-c4fd3039d8d3/) · Anomaly · upstream validation: NOT_TESTED\n- [O365 Email Send Attachments Excessive Volume](https://research.splunk.com/cloud/70a050a2-8537-488a-a628-b60a9558d96a/) · Anomaly · upstream validation: NOT_TESTED\n\n_26 detections are linked in total; the first 12 are shown._",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a"
      }
    },
    "viz_12": {
      "type": "splunk.table",
      "options": {
        "count": 8,
        "backgroundColor": "#22262a"
      },
      "title": "Affected hosts and assets (click a row to search its events)",
      "dataSources": {
        "primary": "ds_9"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\" | eval pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_host=\"$row.host.value$\" | sort 0 _time| head 1000",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_13": {
      "type": "splunk.table",
      "options": {
        "count": 8,
        "backgroundColor": "#22262a"
      },
      "title": "Attack progression by phase (click a row to search it)",
      "dataSources": {
        "primary": "ds_10"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\" | eval pf_phase=coalesce(netspout_pack_phase, netspout_phase) | search pf_phase=\"$row.pf_phase.value$\" | sort 0 _time| head 1000",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_14": {
      "type": "splunk.table",
      "options": {
        "count": 8,
        "backgroundColor": "#22262a"
      },
      "title": "Users and accounts seen in the events",
      "dataSources": {
        "primary": "ds_11"
      },
      "showProgressBar": true
    },
    "viz_15": {
      "type": "splunk.line",
      "options": {
        "seriesColors": [
          "#d4764f",
          "#6f9db5",
          "#c9a24a",
          "#6fa387",
          "#a79fc4",
          "#c9786f",
          "#8fb0a8",
          "#b8b09a"
        ],
        "legendDisplay": "bottom",
        "backgroundColor": "#22262a",
        "yAxisTitleText": "Events",
        "xAxisTitleText": "Seconds since the first event of the run"
      },
      "title": "Telemetry volume trend by source",
      "dataSources": {
        "primary": "ds_12"
      },
      "showProgressBar": true
    },
    "viz_16": {
      "type": "splunk.table",
      "options": {
        "count": 8,
        "backgroundColor": "#22262a"
      },
      "title": "Investigation evidence: security-relevant events (click a row for the raw search)",
      "dataSources": {
        "primary": "ds_13"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\" | eval pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_host=\"$row.host.value$\" pf_st=\"$row.sourcetype.value$\" | sort 0 _time| head 1000",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_17": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Provenance and contract\n**Scenario:** `ind_nonprofit_donor_platform_attack`  \n**Execution:** replay  \n**Telemetry:** Constituent native packs: wave2_cloud_identity_sso_hunt, wave3_cloudmail_exfil (authentic vendor-format telemetry from the vendored attack_data/universe samples; see each pack's contract). Industry framing is editorial.  \n**Sourcetypes:** `OktaIM2:log`, `aws:cloudfront:accesslogs`, `aws:cloudtrail:lake`, `azure:monitor:aad`, `azure:monitor:activity`, `cisco:duo:administrator`, `cisco:secure_access:security_events_ravpn`, `gsuite:gmail:bigquery`, `gws:reports:login`, `o365:graph:messagetrace`, `o365:management:activity`, `o365:reporting:messagetrace`, `zscalernss-web`\n\n**Correlation:** Correlated inside each constituent native pack; constituent packs are related by time only.",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a"
      }
    },
    "viz_18": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Original analytics (Splunk Security Content)\nDetections whose published test data is a dataset replayed by this scenario:\n\n- [ASL AWS Create Access Key](https://research.splunk.com/cloud/81a9f2fe-1697-473c-af1d-086b0d8b63c8/) · Hunting · upstream validation: NOT_TESTED\n- [ASL AWS Create Policy Version to allow all resources](https://research.splunk.com/cloud/22cc7a62-3884-48c4-82da-592b8199b72f/) · TTP · upstream validation: NOT_TESTED\n- [Azure Automation Runbook Created](https://research.splunk.com/cloud/178d696d-6dc6-4ee8-9d25-93fee34eaf5b/) · TTP · upstream validation: NOT_TESTED\n- [Cisco Duo Bulk Policy Deletion](https://research.splunk.com/application/983be012-e408-4cb0-b87f-6756bb5f7047/) · TTP · upstream validation: NOT_TESTED\n- [Cisco Duo Set User Status to Bypass 2FA](https://research.splunk.com/application/8728d224-9cd5-4aa7-b75f-f8520a569979/) · TTP · upstream validation: NOT_TESTED\n- [Detect Web Access to Decommissioned S3 Bucket](https://research.splunk.com/web/3a1d8f62-5b9c-4e7d-b8f3-9d6a8e2f5e1f/) · Anomaly · upstream validation: NOT_TESTED\n- [GCP Successful Single-Factor Authentication](https://research.splunk.com/cloud/40e17d88-87da-414e-b253-8dc1e4f9555b/) · TTP · upstream validation: NOT_TESTED\n- [GSuite Email Suspicious Attachment](https://research.splunk.com/cloud/6d663014-fe92-11eb-ab07-acde48001122/) · Anomaly · upstream validation: NOT_TESTED\n- [Gsuite Outbound Email With Attachment To External Domain](https://research.splunk.com/cloud/dc4dc3a8-ff54-11eb-8bf7-acde48001122/) · Hunting · upstream validation: NOT_TESTED\n- [O365 Email Password and Payroll Compromise Behavior](https://research.splunk.com/cloud/e36de71a-6bdc-4002-98ff-e3e51b0d8f96/) · TTP · upstream validation: NOT_TESTED\n- [O365 Email Receive and Hard Delete Takeover Behavior](https://research.splunk.com/cloud/b66aeaa4-586f-428b-8a2b-c4fd3039d8d3/) · Anomaly · upstream validation: NOT_TESTED\n- [O365 Email Send Attachments Excessive Volume](https://research.splunk.com/cloud/70a050a2-8537-488a-a628-b60a9558d96a/) · Anomaly · upstream validation: NOT_TESTED\n\n_26 detections are linked in total; the first 12 are shown._",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a"
      }
    },
    "viz_19": {
      "type": "splunk.table",
      "options": {
        "count": 8,
        "backgroundColor": "#22262a"
      },
      "title": "Raw event evidence for the run (click a row for the search)",
      "dataSources": {
        "primary": "ds_14"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\" | eval pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_host=\"$row.host.value$\" pf_st=\"$row.sourcetype.value$\" | sort 0 _time| head 1000",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "Events in run",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats count as value"
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Telemetry sources (sourcetypes)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats dc(pf_st) as value"
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Hosts observed",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats dc(pf_host) as value"
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Attack progression span",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats min(_time) as a max(_time) as z | eval value=tostring(round(z-a),\"duration\") | table value"
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Progression phases observed",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats dc(pf_phase) as value"
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Contributing packs",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | eval pk=coalesce(netspout_source_pack, netspout_scenario_id) | stats dc(pk) as value"
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Incident timeline · events by phase",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\"| eventstats min(_time) as pf_t0 max(_time) as pf_t1 | eval pf_w=max(1, ceil((pf_t1-pf_t0)/60)), pf_sec=floor((_time-pf_t0)/pf_w)*pf_w | stats count by pf_sec, pf_phase | xyseries pf_sec pf_phase count | sort pf_sec | fillnull value=0"
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Events by phase (click to filter the page)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats count by pf_phase | sort - count"
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Affected hosts and assets (click a row to search its events)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats count as events, dc(pf_phase) as phases, values(pf_st) as sources, min(_time) as first by pf_host | eval first=strftime(first,\"%H:%M:%S\") | sort - events | head 25 | rename pf_host as host"
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "Attack progression by phase (click a row to search it)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats min(_time) as t0 max(_time) as t1 count as events by pf_phase | sort t0 | eval start=strftime(t0,\"%H:%M:%S\"), seconds=round(t1-t0) | fields start pf_phase events seconds"
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "Users and accounts seen in the events",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | eval who=coalesce(user, User, src_user, TargetUserName, SubjectUserName, Account_Name, 'userIdentity.userName', 'actor.alternateId') | stats count as events, dc(pf_host) as hosts by who | where isnotnull(who) | sort - events | head 25"
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "Telemetry volume trend by source",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\"| eventstats min(_time) as pf_t0 max(_time) as pf_t1 | eval pf_w=max(1, ceil((pf_t1-pf_t0)/60)), pf_sec=floor((_time-pf_t0)/pf_w)*pf_w | stats count by pf_sec, pf_st | xyseries pf_sec pf_st count | sort pf_sec | fillnull value=0"
      }
    },
    "ds_13": {
      "type": "ds.search",
      "name": "Investigation evidence: security-relevant events (click a row for the raw search)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | sort 0 _time | eval time=strftime(_time,\"%H:%M:%S\"), message=substr(_raw,1,200) | table time pf_phase pf_host pf_st message | rename pf_host as host, pf_st as sourcetype | head 200"
      }
    },
    "ds_14": {
      "type": "ds.search",
      "name": "Raw event evidence for the run (click a row for the search)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | sort 0 _time | eval time=strftime(_time,\"%H:%M:%S\"), message=substr(_raw,1,200) | table time pf_phase pf_host pf_st message | rename pf_host as host, pf_st as sourcetype | head 200"
      }
    },
    "ds_runs": {
      "type": "ds.search",
      "name": "Run list",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" | stats latest(_time) as t count by netspout_replay_session | sort - t | eval label=netspout_replay_session.\" · \".strftime(t,\"%m-%d %H:%M\").\" · \".count.\" events\" | table label netspout_replay_session"
      }
    },
    "ds_phase_list": {
      "type": "ds.search",
      "name": "Phase list",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"ind_nonprofit_donor_platform_attack\" netspout_replay_session=\"$run_tok$\" | eval pf_phase=coalesce(netspout_pack_phase, netspout_phase) | stats count by pf_phase | sort pf_phase | eval label=pf_phase | table label pf_phase"
      }
    }
